#!/usr/bin/env bash
# SAHA_SESI_V2 deploy — sahanin sesi: HAM LISTE YOK, sentez temalari. Manuel/Makro kaldirildi. Bugunku cache yeniden uretilir.
set -e
cd /opt/krb-assessment
SRV=server_container.mjs
[ -f "$SRV" ] || { echo "HATA: $SRV yok"; exit 1; }
TS=$(date +%s)
cp "$SRV" "$SRV.bak.$TS"; echo "yedek: $SRV.bak.$TS"
printf '%s' '' | base64 -d > /tmp/patch_saha_sesi_v2.py
python3 /tmp/patch_saha_sesi_v2.py "$SRV"
if ! node --check "$SRV"; then echo "!! node --check BASARISIZ — geri aliniyor"; cp "$SRV.bak.$TS" "$SRV"; exit 1; fi
echo "node --check: OK"
cp shells/kokpit2.html "shells/kokpit2.html.bak.$TS"
printf '%s' '' | base64 -d > shells/kokpit2.html
echo "kokpit2.html satir: $(wc -l < shells/kokpit2.html)"
docker build -t krb-assessment:secure .
docker compose up -d --force-recreate krb-assessment
sleep 4
echo "== ONIZLE: /api/bi/kokpit2 -> Bolum 05 artik SADECE sentez: saha nabzi + emergent + taraf basina derlenmis temalar."
echo "   (Ilk acilista eski gunluk cache reddedilir, V2 yeniden uretir; birkac saniye surebilir.) =="
echo "== DONE =="
